    L += ["", f"---------------- {QUOTED_LABEL} ----------------", pkg.quoted_text or "(none)"]
    if not pkg.attachments:
        L += ["", "---------------- ATTACHMENTS: none ----------------"]
    for i, a in enumerate(pkg.attachments, 1):
        head = f"---------------- ATTACHMENT {i}: {a.source}  [declared: {a.declared_type or '-'} | detected: {a.detected} | status: {a.status}]"
